const themeSelect = document.getElementById('theme-select');
const themeWrapper = document.getElementById('theme-wrapper');

themeSelect.addEventListener('nys-change', (e) => {
  // The wrapper carries one nys-theme-* class at a time. No class means the
  // default NY.gov theme.
  themeWrapper.className = e.detail.value === 'default' ? '' : `nys-theme-${e.detail.value}`;
});
